def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0))

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units <= 1.05:
        scarcity = 2
    elif units <= 1.55:
        scarcity = 1

    opp_bids = []
    desperate_affordable = []
    rich_pressure = []
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            opp_bids.append(float(pbid))
        risk = 0
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 2:
            risk = 1
        afford = min(float(opp.get('budget', 0.0)), float(opp.get('daily_salary', DAILY_SALARY)) * 1.6)
        if risk:
            desperate_affordable.append(afford)
        if opp.get('budget', 0.0) >= 140:
            rich_pressure.append(afford)

    highest_prev = max(opp_bids) if opp_bids else 0.0
    highest_desperate = max(desperate_affordable) if desperate_affordable else 0.0
    highest_rich = max(rich_pressure) if rich_pressure else 0.0

    urgency = 0
    if no_water_days >= 2 or hp <= 2:
        urgency = 2
    elif no_water_days >= 1 or hp <= 4:
        urgency = 1

    base = 0.0
    if urgency == 2:
        base = 96.0
        if scarcity == 2:
            base = 118.0
    elif urgency == 1:
        base = 58.0
        if scarcity == 2:
            base = 84.0
        elif scarcity == 1:
            base = 68.0
    else:
        if scarcity == 2:
            base = 44.0
        elif scarcity == 1:
            base = 28.0
        else:
            base = 12.0

    target = base
    if highest_prev > 0:
        if urgency >= 1 or scarcity >= 1:
            target = max(target, min(highest_prev + 2.0, 112.0))
        else:
            target = max(target, min(highest_prev * 0.45, 36.0))

    if highest_desperate > 0 and (urgency >= 1 or scarcity == 2):
        target = max(target, min(highest_desperate + 1.0, 120.0))

    if highest_rich > 0 and urgency == 0 and scarcity == 0:
        target = min(target, 18.0)

    if day >= 8:
        if urgency >= 1:
            target += 10.0
        else:
            target += 4.0

    reserve_floor = 0.0
    if hp > 4 and no_water_days == 0:
        reserve_floor = DAILY_SALARY * 0.35
    elif hp > 2:
        reserve_floor = DAILY_SALARY * 0.2

    max_spend = budget - reserve_floor
    if urgency == 2:
        max_spend = budget
    elif urgency == 1:
        max_spend = max(max_spend, budget * 0.7)

    if max_spend < 0:
        max_spend = 0.0

    bid = min(target, max_spend)

    if urgency == 0 and scarcity == 0 and highest_prev >= 120:
        bid = min(bid, 10.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # Base safety: if we already are in trouble, bid to secure water.
    if my_hp <= 1 or my_no_water_days >= 2:
        target = DAILY_SALARY * 0.95
    elif my_hp <= 3:
        target = DAILY_SALARY * 0.75
    else:
        target = DAILY_SALARY * 0.58

    # Exploit yesterday trace: if someone bid aggressively, we should not be the cheapest.
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If the strongest opponent was near our salary, we need to match somewhat.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(target, min(my_budget, highest_prev_bid * 0.92))
        # If bids were moderate, slightly overcut the median/mean.
        else:
            avg_prev = sum(prev_bids) / float(len(prev_bids))
            target = max(target, avg_prev * 0.95)

    # Supply pressure: lower supply implies more competition, so raise bid.
    # supply is between 15 and 25 in this meta-round.
    if supply <= (MIN_SUPPLY + 1.0):
        target *= 1.08
    elif supply >= (MAX_SUPPLY - 1.0):
        target *= 0.96

    # Clamp to what we can afford.
    bid = min(my_budget, target)

    # Ensure non-negative and at least a small bid if budget allows.
    if bid < 0:
        bid = 0.0
    if bid == 0.0 and my_budget > 0:
        bid = min(my_budget, DAILY_SALARY * 0.2)

    return float(bid)

